package ma.ebank.ebank; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; public interface AccountRepository extends JpaRepository<BankAccount,String> { @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from BankAccount a where a.id = :id") Optional<BankAccount> locked(@org.springframework.data.repository.query.Param("id") String id); }